		if (isset($this->request->get['store_id']) && $this->request->get['store_id']) {
			$data['store_id'] = $store_id = (int) $this->request->get['store_id'];
      
      $query = $this->db->query("SELECT * FROM " . DB_PREFIX . "setting WHERE store_id = '".$store_id."'");
			
			foreach ($query->rows as $setting) {
				if (!$setting['serialized']) {
					$this->config->set($setting['key'], $setting['value']);
				} else if (version_compare(VERSION, '2.1', '>=')) {
					$this->config->set($setting['key'], json_decode($setting['value'], true));
				} else {
					$this->config->set($setting['key'], unserialize($setting['value']));
				}
			}
    }
    
		// get languages 
		$this->load->model('localisation/language');
		$data['languages'] = $this->model_localisation_language->getLanguages();
    

    if (!empty($this->request->post['extra_page'])) {
      foreach ($this->request->post['extra_page'] as $i => $type) {
        if (empty($type)) continue;
        
        $this->request->post[self::PREFIX.'_page'][$type] = array(
          'on' => !empty($this->request->post['extra_page_on'][$i]),
          'exp' => isset($this->request->post['extra_page_exp'][$i]) ? $this->request->post['extra_page_exp'][$i] : '',
        );
      }
    }
    
    
    if (!empty($this->request->post[self::PREFIX.'_cust_cdn'])) {
      $customCdn = array();
      
      foreach ($this->request->post[self::PREFIX.'_cust_cdn']['source'] as $i => $source) {
        if (empty($source)) continue;
        
        if (!empty($this->request->post['boost_cust_cdn']['target'][$i])) {
          $customCdn[$source] = $this->request->post['boost_cust_cdn']['target'][$i];
        }
      }
      
      $this->request->post[self::PREFIX.'_cust_cdn'] = $customCdn;
    }
    
    
		if (($this->request->server['REQUEST_METHOD'] == 'POST') && ($this->validate())) {
