			$this->model_setting_setting->editSetting(self::PREFIX, $this->request->post, $store_id);
			$this->session->data['success'] = $this->language->get('text_success');
			
			$redirect_store = '';
      
      if ($store_id) {
        $redirect_store = '&store_id=' . $store_id;
      }
      
			if (version_compare(VERSION, '2', '>=')) {
