  public function status() {
    if (!$this->user->hasPermission('modify', self::LINK)) {
      $this->load->language(self::LINK);
      die ($this->language->get('text_demo_mode'));
    }
    
    $this->load->model('setting/setting');
    $newStatus = !$this->config->get('boost_status');
    $this->model_setting_setting->editSettingValue(self::PREFIX, 'boost_status', $newStatus);
    
    echo (int) $newStatus;
    exit;
  }
  
  public function clear_cache_event(&$route, &$data) {
    if (!$this->config->get('boost_status')) return;
    
    $tag = '';
    
    if (!empty($this->request->get['product_id'])) {
      $tag = 'product_id='.$this->request->get['product_id'];
    } else if (!empty($data[1]['product_id'])) {
      $tag = 'product_id='.$data[1]['product_id'];
    } else if (!empty($this->request->get['category_id'])) {
      $tag = 'category_id='.$this->request->get['category_id'];
    } else if (!empty($this->request->get['information_id'])) {
      $tag = 'information_id='.$this->request->get['information_id'];
    }
    
    if (!empty($tag)) {
      $this->boost->deleteItemsByTag($tag);
    } else {
      // full cache clear
      $this->boost->clear(); 
      
      $toDelete = glob(DIR_CACHE . '../boost/*/*');
      foreach ($toDelete as $dir) {
        $this->deleteDir($dir);
      }
    }
  }

  public function optimization() {
    $this->load->model('tool/rocket_boost');
    $this->load->language(self::LINK);
    
    if (!$this->user->hasPermission('modify', self::LINK)) {
      $this->request->get['check'] = 1;
