    if (!empty($this->request->get['type'])) {
      $log = $this->model_tool_rocket_boost->{'optimize_'.$this->request->get['type']}(!empty($this->request->get['check']));
      
      echo '<b>'.$this->language->get('text_opt_'.$this->request->get['type']).'</b><br/><br/>';
    }
    
    echo implode('<br/>', $log);
    
    exit;
  }
  
