  public function save_log() {
    $file = DIR_LOGS.'rocket_boost.log';
    header('Content-Description: File Transfer');
    header('Content-Disposition: attachment; filename=rocket_boost.log');
    header('Content-Type: text/plain');
    header('Cache-Control: must-revalidate');
    header('Content-Length: ' . filesize($file));
    readfile($file);
    exit;
  }
  
  function readLogFile($filename, $lines, $revers = false){
    $offset = -1;
    $c = '';
    $read = '';
    $i = 0;
    $fp = @fopen($filename, "r");
    
    while( $lines && fseek($fp, $offset, SEEK_END) >= 0 ) {
      $c = fgetc($fp);
      if($c == "\n" || $c == "\r"){
        $lines--;
        if( $revers ){
          $read[$i] = strrev($read[$i]);
          $i++;
        }
      }
      if( $revers ) $read[$i] .= $c;
      else $read .= $c;
      $offset--;
    }
    
    fclose ($fp);
    
    if($revers){
      if($read[$i] == "\n" || $read[$i] == "\r")
        array_pop($read);
      else $read[$i] = strrev($read[$i]);
      return implode('',$read);
    }
    
    return strrev(rtrim($read,"\n\r"));
  }
  
  public function process() {
    if (!$this->user->hasPermission('modify', self::LINK)) {
      $this->load->language(self::LINK);
      die($this->language->get('text_demo_mode'));
    }
    
    $this->load->model('localisation/language');
    $languages = $this->model_localisation_language->getLanguages();
    
    //sleep(1);
    ini_set('memory_limit', -1);
    $start_time = time();

    if (!empty($this->request->get['type'])) {
      $data['type'] = $type = str_replace('..', '', $this->request->get['type']);
    } else {
      $data['type'] = $type = '';
    }
    
    if (defined('GKD_CRON')) {
      $this->tool->cron_log($this->language->get('entry_type') . ': ' . $this->language->get('text_type_'.$type));
      $this->tool->cron_log($this->language->get('text_profile_loaded') . ' ' . $this->request->get['profile']);
    }
    
    if (!empty($this->request->get['start'])) {
      $this->load->model('tool/rocket_boost');
      $pagesToCache = $this->model_tool_rocket_boost->getPageList($type);
      
      $total_items = count($pagesToCache);
      
      $init = ($this->request->get['start'] == 'init') ? true : false;
      
      if ($init) {
        $this->clear_cache(true);
      }
      
      $start = (int) $this->request->get['start'];
      
      if (defined('GKD_CRON')) {
        $limit = 9999999999;
      } else {
        $limit = 30;
      }
      
      if ($init) {
        // log
        if ($this->config->get('rocket_boost_log')) {
          $this->tool->log("###### Start RocketBoost Process - ".date('d/m/Y H:i:s')." ######");
        }
      }
      
      $items_processed = 0;
      
      $extraParams = array('');
      
      if (defined('JOURNAL3_INSTALLED')) {
        $extraParams[] = 'gkdrb[]=mobile';
      }
      
      foreach ($pagesToCache as $i => $url) {
        usleep(10 * 1000);  // 1 000 000 = 1s
        
        if ($i < $start) {
          continue;
        }
        
        if (!defined('GKD_CRON') && (time() - 12) > $start_time) {
          break;
        }
        
        if ($items_processed > $limit) {
          break;
        }
                
        foreach ($languages as $lang) {
          foreach ($extraParams as $extraParam) {
            if ($extraParam) {
              @file_get_contents($url.(strpos($url, '?') ? '&' : '?').'gkdrblg='.$lang['code'].'&'.$extraParam);
            } else {
              @file_get_contents($url.(strpos($url, '?') ? '&' : '?').'gkdrblg='.$lang['code']);
            }
          }
        }
        
        $items_processed++;
      }
      
      $processed = $start + $items_processed;
      //$processed = $start + $items_processed; //issue with product options by row
      
      if ($processed > $total_items) {
        $processed = $total_items;
      }
      
      if ($processed >= $total_items) {
        if ($this->config->get('rocket_boost_log')) {
          $this->tool->log("###### End RocketBoost Process - ".date('d/m/Y H:i:s')." ######\n");
        }
      }
      
      if ($total_items == 0 || !$items_processed) {
        $progress = 100;
      } else {
        $progress = floor(($processed / $total_items) * 100);
      }
      
      header('Content-type: application/json');
      echo json_encode(array(
        'success'=> 1,
        'processed' => $processed,
        'progress' => $progress,
        'finished' => (($processed >= $total_items) || !$items_processed),
        //'mem' => memory_get_usage()
      ));
      
    }
	}
  
