     // settings
		$this->load->model('setting/setting');
		$this->model_setting_setting->editSetting(self::PREFIX, array(
      self::PREFIX.'_page' => array(
        'common/home' => array('on' => 1),
        'product/category' => array('on' => 1),
        'product/product' => array('on' => 1),
        'product/manufacturer' => array('on' => 1),
        'information/information' => array('on' => 1),
        'product/special' => array('on' => 1),
        'information/sitemap' => array('on' => 1),
      ),
    ));
    
    // tables
		$this->db_tables();
		
		//header('Location:index.php?route=extension/module&' . $this->token);
	}
	
	public function uninstall() {
    if (version_compare(VERSION, '3', '<')) {
      $this->load->model('extension/event');
      $eventModel = 'model_extension_event';
      $eventMethod = 'deleteEvent';
    } else {
      $this->load->model('setting/event');
      $eventModel = 'model_setting_event';
      $eventMethod = 'deleteEventByCode';
    }
    
    foreach ($this->eventsArray as $event) {
      list($code, $trigger, $action) = explode(';', $event);
      
      $this->{$eventModel}->{$eventMethod}($code);
    }
  }
	
	private function validate() {
		if (!$this->user->hasPermission('modify', self::LINK)) {
			$this->error['error'] = $this->language->get('error_permission');
		}
      
		if (!$this->error)
			return true;
		return false;
	}
  
  private function db_tables() {
    // events
    if (version_compare(VERSION, '3', '<')) {
      $this->load->model('extension/event');
      $eventModel = 'model_extension_event';
      $eventMethod = 'getEvent';
    } else {
      $this->load->model('setting/event');
      $eventModel = 'model_setting_event';
      $eventMethod = 'getEventByCode';
    }
    
    foreach ($this->eventsArray as $event) {
      list($code, $trigger, $action) = explode(';', $event);
      
      if (version_compare(VERSION, '3', '<')) {
        $eventExists = $this->{$eventModel}->{$eventMethod}($code, $trigger, $action);
      } else {
        $eventExists = $this->{$eventModel}->{$eventMethod}($code);
      }
      
      if (!$eventExists) {
        $this->{$eventModel}->addEvent($code, $trigger, $action);
      }
    }
	}
